// TAB NAVIGATION CONTROLLER
function switchTab(tabId) {
  ['dashboard', 'items', 'health', 'settings'].forEach(id => {
    const view = document.getElementById(`view-${id}`);
    const btn = document.getElementById(`tab-btn-${id}`);
    if (id === tabId) {
      if (view) view.classList.remove('hidden');
      if (btn) btn.className = "px-3.5 py-1.5 rounded-lg font-medium transition-all duration-150 flex items-center gap-2 bg-emerald-500 text-white shadow-sm";
    } else {
      if (view) view.classList.add('hidden');
      if (btn) btn.className = "px-3.5 py-1.5 rounded-lg font-medium transition-all duration-150 flex items-center gap-2 text-[var(--muted-foreground,#94a3b8)] hover:text-white hover:bg-[var(--card,#1e293b)]";
    }
  });
  if (tabId === 'dashboard') renderPriceChart();
}

// USER PROFILE DROPDOWN MENU CONTROLLER
function toggleUserDropdown(event) {
  if (event) event.stopPropagation();
  const menu = document.getElementById('user-dropdown-menu');
  menu.classList.toggle('hidden');
}

function selectSettingsFromMenu() {
  const menu = document.getElementById('user-dropdown-menu');
  if (menu) menu.classList.add('hidden');
  switchTab('settings');
  showToast('Opened G-Sync & Configuration', 'info');
}

function handleSignOut() {
  const menu = document.getElementById('user-dropdown-menu');
  if (menu) menu.classList.add('hidden');
  showToast('Google OAuth session reset. Redirecting...', 'info');
}

// Close dropdown on click outside or escape key
window.addEventListener('click', (e) => {
  const menu = document.getElementById('user-dropdown-menu');
  const btn = document.getElementById('user-menu-btn');
  if (menu && !menu.classList.contains('hidden')) {
    if (!menu.contains(e.target) && (!btn || !btn.contains(e.target))) {
      menu.classList.add('hidden');
    }
  }
});

window.addEventListener('keydown', (e) => {
  if (e.key === 'Escape') {
    const menu = document.getElementById('user-dropdown-menu');
    if (menu) menu.classList.add('hidden');
    closeAddItemModal();
  }
});

