// =========================================================================
// CATEGORY & LABEL AGGREGATION SYSTEM & SYNC
// =========================================================================
function renderCategoryAggregations() {
  const container = document.getElementById('dashboard-category-chips');
  if (container) {
    container.innerHTML = '';
  }
  renderTableLabelFilterBar();
}

function renderTableLabelFilterBar() {
  const bar = document.getElementById('table-label-filter-bar');
  if (!bar) return;
  bar.innerHTML = '<span class="text-slate-500 text-[11px] flex-shrink-0 font-medium">Filter by Label:</span>';

  // Gather distinct categories and custom tags from items and registry
  const set = new Set();
  state.items.forEach(i => {
    if (i.category) set.add(i.category);
    (i.customTags || []).forEach(t => set.add(t));
  });

  const labels = ['ALL', ...Array.from(set)];
  labels.forEach(l => {
    const isActive = state.activeLabelFilter === l;
    const btn = document.createElement('button');
    btn.className = `px-2.5 py-0.5 rounded-lg text-[11px] font-semibold whitespace-nowrap transition border ${isActive ? 'bg-emerald-500 text-white border-emerald-400' : 'bg-slate-800 text-slate-300 border-slate-700 hover:text-white'}`;
    btn.innerText = l === 'ALL' ? 'Show All' : (state.tagRegistry.some(t => t.name === l && t.type === 'custom') ? `🏷️ ${l}` : l);
    btn.onclick = () => selectLabelFilter(l);
    bar.appendChild(btn);
  });
}

function selectLabelFilter(labelName) {
  state.activeLabelFilter = labelName;
  state.currentPage = 1;
  renderTableLabelFilterBar();
  applyFiltersAndSort();

  // Bi-directional sync: Update chart category dropdown
  const chartSelect = document.getElementById('chart-category-filter');
  if (chartSelect && chartSelect.value !== labelName) {
    let hasOpt = false;
    for (let opt of chartSelect.options) {
      if (opt.value === labelName) { hasOpt = true; break; }
    }
    if (!hasOpt && labelName !== 'ALL') {
      const opt = document.createElement('option');
      opt.value = labelName;
      opt.innerText = `🏷️ ${labelName}`;
      chartSelect.appendChild(opt);
    }
    chartSelect.value = labelName;
  }

  // Sync chart series
  filterChartByCategory(labelName, true);
}

