  state.items.forEach(item => {
    if (!catStats[item.category]) {
      catStats[item.category] = { count: 0, sumDrop: 0, discountedCount: 0 };
    }
    catStats[item.category].count++;
    catStats[item.category].sumDrop += item.dropPct;
    if (item.dropPct > 0) catStats[item.category].discountedCount++;
  });

  // "All Items" master chip
  const isAllActive = state.activeLabelFilter === 'ALL';
  const allChip = document.createElement('button');
  allChip.className = `px-3 py-1.5 rounded-xl text-xs font-semibold whitespace-nowrap transition flex items-center gap-1.5 border ${isAllActive ? 'bg-emerald-500 text-white border-emerald-400 shadow-md shadow-emerald-500/20' : 'bg-slate-800/80 text-slate-300 border-slate-700 hover:bg-slate-700'}`;
  allChip.onclick = () => selectLabelFilter('ALL');
  allChip.innerHTML = `<span>✨ All Items</span><span class="bg-black/30 px-1.5 py-0.2 rounded-full font-mono text-[10px]">${state.items.length}</span>`;
  container.appendChild(allChip);

  // Render category chips
  Object.keys(catStats).forEach(catName => {
    const stat = catStats[catName];
    const avgDrop = Math.round(stat.sumDrop / stat.count);
    const isActive = state.activeLabelFilter === catName;

    const chip = document.createElement('button');
    chip.className = `px-3 py-1.5 rounded-xl text-xs font-semibold whitespace-nowrap transition flex items-center gap-1.5 border ${isActive ? 'bg-emerald-500 text-white border-emerald-400 shadow-md shadow-emerald-500/20' : 'bg-slate-800/80 text-slate-300 border-slate-700 hover:bg-slate-700 hover:text-white'}`;
    chip.onclick = () => selectLabelFilter(catName);
    chip.innerHTML = `
      <span>${catName}</span>
      <span class="bg-black/30 px-1.5 py-0.2 rounded-full font-mono text-[10px]">${stat.count}</span>
      ${avgDrop > 0 ? `<span class="text-[10px] text-emerald-300 font-mono font-bold">-${avgDrop}% avg</span>` : ''}
    `;
    container.appendChild(chip);
  });

  // Render custom tags chip: "Black Friday" & "Gift Idea"
  ['Black Friday', 'Gift Idea'].forEach(tag => {
    const count = state.items.filter(i => i.customTags.includes(tag)).length;
    const isActive = state.activeLabelFilter === tag;
    const chip = document.createElement('button');
    chip.className = `px-3 py-1.5 rounded-xl text-xs font-semibold whitespace-nowrap transition flex items-center gap-1.5 border ${isActive ? 'bg-amber-500 text-black border-amber-400 font-bold' : 'bg-amber-500/10 text-amber-300 border-amber-500/30 hover:bg-amber-500/20'}`;
    chip.onclick = () => selectLabelFilter(tag);
    chip.innerHTML = `
      <span>🏷️ ${tag}</span>
      <span class="bg-black/30 px-1.5 py-0.2 rounded-full font-mono text-[10px]">${count}</span>
    `;
    container.appendChild(chip);
  });

  // Render Tabular Quick Label Bar
  renderTableLabelFilterBar();
}

function renderTableLabelFilterBar() {
  const bar = document.getElementById('table-label-filter-bar');
  bar.innerHTML = '<span class="text-slate-500 text-[11px] flex-shrink-0 font-medium">Filter by Label:</span>';

  const labels = ['ALL', 'Audio', 'Laptops', 'Smartphones', 'TVs & Displays', 'Gaming', 'Cameras & Drones', 'Black Friday', 'Gift Idea'];
  labels.forEach(l => {
    const isActive = state.activeLabelFilter === l;
    const btn = document.createElement('button');
    btn.className = `px-2.5 py-0.5 rounded-lg text-[11px] font-semibold whitespace-nowrap transition border ${isActive ? 'bg-emerald-500 text-white border-emerald-400' : 'bg-slate-800 text-slate-300 border-slate-700 hover:text-white'}`;
    btn.innerText = l === 'ALL' ? 'Show All' : l;
    btn.onclick = () => selectLabelFilter(l);
    bar.appendChild(btn);
  });
}

function selectLabelFilter(labelName) {
  state.activeLabelFilter = labelName;
  state.currentPage = 1;
  renderCategoryAggregations();
  applyFiltersAndSort();

  // If specific category selected, also sync chart series
  if (labelName !== 'ALL') {
    const matchingIds = state.items.filter(i => i.category === labelName || i.customTags.includes(labelName)).map(i => i.id);
    if (matchingIds.length > 0) {
      state.selectedSeriesIds = matchingIds.slice(0, 8); // Top 8 in that category
      renderNormalizedPercentageChart();
    }
  }
}

