function filterChartByCategory(catVal, skipGridSync = false) {
  if (catVal === 'ALL') {
    state.selectedSeriesIds = [...state.items].sort((a,b) => b.dropPct - a.dropPct).slice(0, 8).map(i => i.id);
  } else {
    state.selectedSeriesIds = state.items.filter(i => 
      i.category === catVal || 
      (i.customTags && i.customTags.includes(catVal)) ||
      i.store === catVal
    ).map(i => i.id);
  }
  renderNormalizedPercentageChart();

  // Bi-directional sync with table data grid
  if (!skipGridSync) {
    state.activeLabelFilter = catVal;
    state.currentPage = 1;
    renderTableLabelFilterBar();
    applyFiltersAndSort();
    showToast(`Chart & Data Grid synchronized to "${catVal}" (${state.selectedSeriesIds.length} items)`, 'info');
  }
}

// =========================================================================
// TAG & CATEGORY TAXONOMY MANAGER CONTROLLER
// =========================================================================
function toggleNewTagForm() {
  const form = document.getElementById('tagmgr-create-form');
  if (form) form.classList.toggle('hidden');
}

function filterTagManagerView(type) {
  state.tagFilterMode = type;
  ['all', 'custom', 'category', 'retailer'].forEach(t => {
    const btn = document.getElementById(`tagmgr-btn-${t}`);
    if (btn) {
      if (t === type) {
        btn.className = "px-3 py-1.5 rounded-xl text-xs font-semibold bg-emerald-500 text-white border border-emerald-400";
      } else {
        btn.className = "px-3 py-1.5 rounded-xl text-xs font-semibold text-slate-300 hover:text-white bg-slate-800/80 border border-slate-700";
      }
    }
  });
  renderTagCardsGrid();
}

function createNewTagFromManager() {
  const nameInput = document.getElementById('tagmgr-input-name');
  const typeSelect = document.getElementById('tagmgr-select-type');
  const colorSelect = document.getElementById('tagmgr-select-color');

  const name = nameInput.value.trim();
  if (!name) {
    showToast('Please enter a tag name', 'error');
    return;
  }

  const type = typeSelect.value;
  const color = colorSelect.value;

  // Check if already exists in registry
  const exists = state.tagRegistry.some(t => t.name.toLowerCase() === name.toLowerCase());
  if (exists) {
    showToast(`Tag "${name}" already exists!`, 'error');
    return;
  }

  state.tagRegistry.unshift({
    name: name,
    type: type,
    color: color,
    icon: type === 'custom' ? '🏷️' : (type === 'category' ? '📂' : '🛒')
  });

  nameInput.value = '';
  toggleNewTagForm();
  renderTagManagerPage();
  renderTableLabelFilterBar();
  updateChartCategoryFilterOptions();
  showToast(`Created tag "${name}" successfully!`, 'success');
}

function updateChartCategoryFilterOptions() {
  const select = document.getElementById('chart-category-filter');
  if (!select) return;
  const cur = select.value;
  select.innerHTML = '<option value="ALL">All Categories & Tags (99)</option>';

  // Add system categories
  const categories = ['Audio', 'Laptops', 'Smartphones', 'TVs & Displays', 'Gaming', 'Cameras & Drones', 'Smart Home'];
  categories.forEach(c => {
    const opt = document.createElement('option');
    opt.value = c;
    opt.innerText = c;
    select.appendChild(opt);
  });

  // Add custom tags
  const customTags = state.tagRegistry.filter(t => t.type === 'custom').map(t => t.name);
  customTags.forEach(t => {
    const opt = document.createElement('option');
    opt.value = t;
    opt.innerText = `🏷️ Tag: ${t}`;
    select.appendChild(opt);
  });

  select.value = cur;
}

function renderTagManagerPage() {
  // Update top counts
  const totalCount = state.tagRegistry.length;
  const customCount = state.tagRegistry.filter(t => t.type === 'custom').length;
  const catCount = state.tagRegistry.filter(t => t.type === 'category').length;
  const retCount = state.tagRegistry.filter(t => t.type === 'retailer').length;

  const elTotal = document.getElementById('tagmgr-total-count');
  if (elTotal) elTotal.innerText = totalCount;
  const elAll = document.getElementById('tagmgr-count-all');
  if (elAll) elAll.innerText = totalCount;
  const elCustom = document.getElementById('tagmgr-count-custom');
  if (elCustom) elCustom.innerText = customCount;
  const elCat = document.getElementById('tagmgr-count-category');
  if (elCat) elCat.innerText = catCount;
  const elRet = document.getElementById('tagmgr-count-retailer');
  if (elRet) elRet.innerText = retCount;

  renderTagCardsGrid();
}

function renderTagCardsGrid() {
  const container = document.getElementById('tagmgr-cards-grid');
  if (!container) return;
  container.innerHTML = '';

  const query = (document.getElementById('tagmgr-search-input')?.value || '').toLowerCase();
  let list = [...state.tagRegistry];

  if (state.tagFilterMode !== 'all') {
    list = list.filter(t => t.type === state.tagFilterMode);
  }

  if (query) {
    list = list.filter(t => t.name.toLowerCase().includes(query) || t.type.toLowerCase().includes(query));
  }

  if (list.length === 0) {
    container.innerHTML = '<div class="col-span-3 py-12 text-center text-slate-500 text-xs">No tags found matching current criteria.</div>';
    return;
  }

  const colorMap = {
    emerald: { bg: 'bg-emerald-500/10', border: 'border-emerald-500/30', text: 'text-emerald-400', badge: 'bg-emerald-500/20 text-emerald-300' },
    blue: { bg: 'bg-blue-500/10', border: 'border-blue-500/30', text: 'text-blue-400', badge: 'bg-blue-500/20 text-blue-300' },
    purple: { bg: 'bg-purple-500/10', border: 'border-purple-500/30', text: 'text-purple-400', badge: 'bg-purple-500/20 text-purple-300' },
    amber: { bg: 'bg-amber-500/10', border: 'border-amber-500/30', text: 'text-amber-400', badge: 'bg-amber-500/20 text-amber-300' },
    rose: { bg: 'bg-rose-500/10', border: 'border-rose-500/30', text: 'text-rose-400', badge: 'bg-rose-500/20 text-rose-300' },
    cyan: { bg: 'bg-cyan-500/10', border: 'border-cyan-500/30', text: 'text-cyan-400', badge: 'bg-cyan-500/20 text-cyan-300' }
  };

  list.forEach(tag => {
    // Calculate matching active items
    const matching = state.items.filter(i => {
      if (tag.type === 'category') return i.category === tag.name;
      if (tag.type === 'retailer') return i.store === tag.name;
      return i.customTags && i.customTags.includes(tag.name);
    });

    // Calculate matching bought items
    const boughtMatching = state.boughtItems.filter(b => {
      if (tag.type === 'category') return b.category === tag.name;
      if (tag.type === 'retailer') return b.store === tag.name;
      return b.customTags && b.customTags.includes(tag.name);
    });

    const sumDrop = matching.reduce((acc, cur) => acc + cur.dropPct, 0);
    const avgDrop = matching.length > 0 ? Math.round(sumDrop / matching.length) : 0;
    const boughtSavings = boughtMatching.reduce((acc, cur) => acc + cur.savedCost, 0);

    const theme = colorMap[tag.color] || colorMap.purple;

    const card = document.createElement('div');
    card.className = `bg-[var(--card,#111827)] border border-slate-800 rounded-2xl p-5 shadow-sm space-y-4 hover:border-slate-700 transition flex flex-col justify-between`;

    // Attached items previews (top 3)
    const previewItemsHtml = matching.slice(0, 3).map(m => `
      <div class="flex items-center gap-1.5 py-0.5">
        <span class="w-1.5 h-1.5 rounded-full bg-slate-500"></span>
        <span class="text-[11px] text-slate-300 truncate max-w-[210px]">${m.name}</span>
      </div>
    `).join('') || '<span class="text-[11px] text-slate-500 italic">No active items attached.</span>';

    card.innerHTML = `
      <div>
        <div class="flex items-start justify-between gap-2 pb-3 border-b border-slate-800/80">
          <div class="flex items-center gap-2">
            <span class="px-2.5 py-1 rounded-xl text-xs font-bold border ${theme.bg} ${theme.border} ${theme.text} flex items-center gap-1.5">
              <span>${tag.icon || '🏷️'}</span>
              <span>${tag.name}</span>
            </span>
            <span class="text-[9px] uppercase font-mono px-1.5 py-0.5 rounded bg-slate-800 text-slate-400">
              ${tag.type}
            </span>
          </div>
          <span class="text-xs font-mono font-bold text-slate-200">
            ${matching.length} items
          </span>
        </div>

        <!-- Stats Row -->
        <div class="grid grid-cols-2 gap-2 my-3 text-xs">
          <div class="bg-slate-900/60 p-2.5 rounded-xl border border-slate-800/80">
            <p class="text-[10px] text-slate-400 uppercase font-semibold">Average Drop</p>
            <p class="text-sm font-bold font-mono ${avgDrop > 0 ? 'text-emerald-400' : 'text-slate-400'} mt-0.5">
              ${avgDrop > 0 ? '-' + avgDrop + '%' : '0% (Baseline)'}
            </p>
          </div>
          <div class="bg-slate-900/60 p-2.5 rounded-xl border border-slate-800/80">
            <p class="text-[10px] text-slate-400 uppercase font-semibold">Realized Savings</p>
            <p class="text-sm font-bold font-mono text-emerald-400 mt-0.5">
              $${boughtSavings.toFixed(2)}
            </p>
          </div>
        </div>

        <!-- Sample Attached Items -->
        <div>
          <p class="text-[10px] font-semibold uppercase text-slate-400 mb-1">Attached Items Preview</p>
          <div class="space-y-0.5">
            ${previewItemsHtml}
          </div>
        </div>
      </div>

      <!-- Action Buttons -->
      <div class="pt-3 border-t border-slate-800/80 flex items-center justify-between gap-2">
        <button onclick="jumpToTagInGrid('${tag.name}')" class="flex-1 py-1.5 rounded-xl bg-emerald-500/10 hover:bg-emerald-500/20 text-emerald-400 border border-emerald-500/30 text-[11px] font-bold transition flex items-center justify-center gap-1">
          <span>View in Grid</span>
          <span>&rarr;</span>
        </button>
        <button onclick="promptRenameTag('${tag.name}')" class="px-2.5 py-1.5 rounded-xl bg-slate-800 hover:bg-slate-700 text-slate-300 text-[11px] font-medium transition" title="Rename Tag">
          ✏️
        </button>
        ${tag.type === 'custom' ? `
          <button onclick="deleteTagFromManager('${tag.name}')" class="px-2.5 py-1.5 rounded-xl bg-rose-500/10 hover:bg-rose-500/20 text-rose-400 border border-rose-500/30 text-[11px] font-medium transition" title="Delete Tag">
            🗑️
          </button>
        ` : ''}
      </div>
    `;

    container.appendChild(card);
  });
}

function jumpToTagInGrid(tagName) {
  switchTab('dashboard');
  selectLabelFilter(tagName);
  showToast(`Filtered Grid & Trajectory Chart to "${tagName}"`, 'info');
}

function promptRenameTag(oldName) {
  const newName = prompt(`Rename tag "${oldName}" to:`, oldName);
  if (!newName || newName.trim() === '' || newName.trim() === oldName) return;

  const trimmed = newName.trim();

  // Update in registry
  const tagObj = state.tagRegistry.find(t => t.name === oldName);
  if (tagObj) tagObj.name = trimmed;

  // Update in active items
  state.items.forEach(i => {
    if (i.category === oldName) i.category = trimmed;
    if (i.store === oldName) i.store = trimmed;
    if (i.customTags) {
      i.customTags = i.customTags.map(t => t === oldName ? trimmed : t);
    }
  });

  // Update in bought items
  state.boughtItems.forEach(b => {
    if (b.category === oldName) b.category = trimmed;
    if (b.store === oldName) b.store = trimmed;
    if (b.customTags) {
      b.customTags = b.customTags.map(t => t === oldName ? trimmed : t);
    }
  });

  renderAll();
  renderTagManagerPage();
  updateChartCategoryFilterOptions();
  showToast(`Tag renamed to "${trimmed}" across all items!`, 'success');
}

function deleteTagFromManager(tagName) {
  if (!confirm(`Are you sure you want to remove tag "${tagName}" from all monitored items?`)) return;

  // Remove from registry
  state.tagRegistry = state.tagRegistry.filter(t => t.name !== tagName);

  // Untag in active items
  state.items.forEach(i => {
    if (i.customTags) {
      i.customTags = i.customTags.filter(t => t !== tagName);
    }
  });

  // Untag in bought items
  state.boughtItems.forEach(b => {
    if (b.customTags) {
      b.customTags = b.customTags.filter(t => t !== tagName);
    }
  });

  if (state.activeLabelFilter === tagName) {
    state.activeLabelFilter = 'ALL';
  }

  renderAll();
  renderTagManagerPage();
  updateChartCategoryFilterOptions();
  showToast(`Removed tag "${tagName}" from all items`, 'info');
}

